const opType = msg.operationType || 'read';

if (opType === 'write') {
    return [null, msg];
} else {
    return [msg, null];
}

// Save RPC response topic and write result
flow.set("scs_rpc_response_topic", msg.rpcResponseTopic);
flow.set("scs_write_result", msg.writeResult || null);

// Clear previous collected data
flow.set("scs_reads", null);

// Read all registers in parallel
const reads = [
    { name: 'deviceType', address: 100, quantity: 1 },
    { name: 'serialNumber', address: 103, quantity: 5 },
    { name: 'firmware', address: 114, quantity: 5 },
    { name: 'ratedPower', address: 120, quantity: 2 },
    { name: 'gridStandard', address: 282, quantity: 1 },
    { name: 'gridFrequency', address: 283, quantity: 1 },
    { name: 'gridType', address: 284, quantity: 1 },
    { name: 'voltageLevel', address: 238, quantity: 1 },
    { name: 'phaseSequence', address: 247, quantity: 1 },
    { name: 'batteryMode', address: 211, quantity: 1 },
    { name: 'batteryCapacity', address: 202, quantity: 1 },
    { name: 'genInputMode', address: 233, quantity: 1 },
    { name: 'genConnectedGrid', address: 289, quantity: 1 },
    { name: 'exportLimitMode', address: 242, quantity: 1 }
];

const messages = reads.map(r => ({
    payload: {
        fc: 3,
        unitid: 1,
        address: r.address,
        quantity: r.quantity
    },
    readName: r.name
}));

return [messages];

const flowKey = 'scs_reads';
let collected = flow.get(flowKey) || {};
let expectedCount = 14;

let data = msg.payload;
if (data && Array.isArray(data.data)) {
    data = data.data;
}

if (!Array.isArray(data) || data.length < 1) {
    node.status({ fill: "red", shape: "dot", text: "Read failed: " + msg.readName });
    return null;
}

const readName = msg.readName;

// Store the data based on type
if (readName === 'serialNumber' || readName === 'firmware' || readName === 'ratedPower') {
    collected[readName] = data;
} else {
    collected[readName] = data[0];
}

flow.set(flowKey, collected);

const collectedCount = Object.keys(collected).length;
node.status({ fill: "blue", shape: "dot", text: `Collected ${collectedCount}/${expectedCount}` });

if (collectedCount >= expectedCount) {
    flow.set(flowKey, null);
    msg.collectedData = collected;
    msg.payload = collected;
    return msg;
}

return null;

const data = msg.collectedData;

if (!data) {
    node.status({ fill: "red", shape: "dot", text: "No data" });
    return null;
}

const gatewayId = global.get("GATEWAY_ID") || env.get("GATEWAY_ID") || "EC100-GW-001";

// Parse Serial Number (5 registers = 10 ASCII)
function parseSerialNumber(regs) {
    let sn = "";
    for (let i = 0; i < regs.length; i++) {
        const highByte = (regs[i] >> 8) & 0xFF;
        const lowByte = regs[i] & 0xFF;
        sn += String.fromCharCode(highByte);
        sn += String.fromCharCode(lowByte);
    }
    return sn.replace(/\0/g, '').trim();
}

const serialNumber = parseSerialNumber(data.serialNumber);

// Parse device type and derive model
const deviceType = data.deviceType;
let inverterModel = "Unknown";
if (deviceType === 0x03) inverterModel = "Single-phase LV hybrid";
else if (deviceType === 0x05) inverterModel = "Three-phase LV hybrid";
else if (deviceType === 0x06) inverterModel = "Three-phase HV hybrid";

const gridPhaseCount = (deviceType === 0x05 || deviceType === 0x06) ? 3 : 1;

// Parse firmware versions
const fw = data.firmware;
const firmware = {
    protocolVersion: null,
    mcuBoardRaw: null,
    controlHardwareRaw: fw[0],
    controlMainRaw: fw[1],
    commField1Raw: fw[2],
    commField2Raw: fw[3],
    commMainRaw: fw[4]
};

// Parse rated power (32-bit)
const ratedPowerRaw = (data.ratedPower[1] << 16) | data.ratedPower[0];
const ratedPowerW = ratedPowerRaw / 10;

// Parse grid frequency
const gridFrequencyHz = data.gridFrequency === 0 ? 50 : 60;

// Parse grid phase sequence
const gridPhaseSequence = data.phaseSequence === 0 ? "ABC_0_120_240" : "ACB_0_240_120";

// Parse grid type (284)
const gridTypeMap = {
    0x00: "single_phase",
    0x01: "two_phase",
    0x02: "three_phase_208v",
    0x03: "single_phase_120v"
};
const gridType = gridTypeMap[data.gridType] !== undefined ? gridTypeMap[data.gridType] : data.gridType;

// Parse battery control mode
const batteryModeMap = { 0: "voltage", 1: "capacity", 2: "no_battery" };
const batteryControlMode = batteryModeMap[data.batteryMode] || "no_battery";

// Parse generator input mode
const genInputModeMap = { 0: "generator_input", 1: "smart_load", 2: "micro_inverter_input" };
const genInputMode = genInputModeMap[data.genInputMode] || "generator_input";

// Parse export limit mode
const exportLimitModeMap = { 0x00: "sell_enabled", 0x01: "internal_meter", 0x02: "external_ct" };
const exportLimitMode = exportLimitModeMap[data.exportLimitMode] || "sell_enabled";

// Build the complete structure
const structure = {
    kind: "SystemConnectionStructure",
    timestampUtc: new Date().toISOString(),
    version: 1,
    DeviceId: gatewayId,
    schemaVersion: 1,

    inverter: {
        deviceType: deviceType,
        inverterModel: inverterModel,
        serialNumber: serialNumber,
        firmware: firmware,
        ratedPowerW: ratedPowerW,

        acSide: {
            mpptAndPhasesRaw: null,
            batteryInputCount: null,
            outputTopology: null,
            gridType: gridType,
            regionVariant: null,
            safetyTypeRaw: null,
            gridPhaseCount: gridPhaseCount,
            gridStandardRaw: data.gridStandard,
            gridFrequencyHz: gridFrequencyHz,
            gridVoltageLevelCode: data.voltageLevel,
            gridPhaseSequence: gridPhaseSequence,
            itSystemNeutralUngrounded: null
        }
    },

    battery: {
        batteryControlMode: batteryControlMode,
        batteryChannels: [{
            channelId: 1,
            ratedCapacityAh: data.batteryCapacity,
            nominalVoltageV: null,
            batterySn: null,
            batteryPhysicalAddress: null,
            batterySoftwareVersion: null,
            lithiumBatteryType: null
        }]
    },

    generator: {
        inputMode: genInputMode,
        connectedToGridInput: data.genConnectedGrid === 1
    },

    pv: {
        mpptCount: null,
        mppt: [
            { pvChannelId: 1, supportsInput: true, stringMaxCurrentA: null, stringMaxVoltageV: null, recommendedVocAtStcV: null },
            { pvChannelId: 2, supportsInput: true, stringMaxCurrentA: null, stringMaxVoltageV: null, recommendedVocAtStcV: null },
            { pvChannelId: 3, supportsInput: true, stringMaxCurrentA: null, stringMaxVoltageV: null, recommendedVocAtStcV: null },
            { pvChannelId: 4, supportsInput: true, stringMaxCurrentA: null, stringMaxVoltageV: null, recommendedVocAtStcV: null }
        ]
    },

    loadAndGrid: {
        homeLoadConnectionPoint: null,
        exportLimitMode: exportLimitMode,
        currentTransformerOnGridSide: null,
        supportsBackupLoad: null,
        supportsZeroExport: null,
        supportsExternalMeter: null
    }
};

// Get write result and rpc topic
const writeResult = flow.get("scs_write_result");
const rpcResponseTopic = flow.get("scs_rpc_response_topic");

flow.set("scs_write_result", null);
flow.set("scs_rpc_response_topic", null);

if (writeResult) {
    msg.payload = {
        success: writeResult.success,
        message: writeResult.message,
        writes: writeResult.writes,
        state: structure
    };
} else {
    msg.payload = structure;
}

msg.state = structure;
msg.rpcResponseTopic = rpcResponseTopic;

node.status({ fill: "green", shape: "dot", text: `${inverterModel} - SN: ${serialNumber}` });

return msg;

if (!msg.rpcResponseTopic) {
    return null;
}

msg.topic = msg.rpcResponseTopic;
return msg;

// Parse RPC params and build write queue
const params = msg.rpcParams || {};
const writes = [];

// ═══════════════════════════════════════════════════════════
// AC SIDE SETTINGS
// ═══════════════════════════════════════════════════════════

// Register 284: gridType [0-3]
if (params.gridType !== undefined) {
    let numVal = params.gridType;
    if (typeof numVal === 'string') {
        const map = { 'single_phase': 0, 'two_phase': 1, 'three_phase_208v': 2, 'single_phase_120v': 3 };
        numVal = map[numVal];
    }
    if (numVal >= 0 && numVal <= 3) {
        writes.push({ register: 284, value: numVal, name: 'Grid Type' });
    }
}

// Register 282: gridStandardRaw [0-4]
if (params.gridStandardRaw !== undefined) {
    const val = params.gridStandardRaw;
    if (val >= 0 && val <= 4) {
        writes.push({ register: 282, value: val, name: 'Grid Standard' });
    }
}

// Register 283: gridFrequencyHz [0=50Hz, 1=60Hz]
if (params.gridFrequencyHz !== undefined) {
    let numVal = params.gridFrequencyHz;
    // Accept 50/60 or 0/1
    if (numVal === 50) numVal = 0;
    else if (numVal === 60) numVal = 1;
    if (numVal === 0 || numVal === 1) {
        writes.push({ register: 283, value: numVal, name: 'Grid Frequency' });
    }
}

// Register 238: gridVoltageLevelCode [0-4]
if (params.gridVoltageLevelCode !== undefined) {
    const val = params.gridVoltageLevelCode;
    if (val >= 0 && val <= 4) {
        writes.push({ register: 238, value: val, name: 'Voltage Level' });
    }
}

// Register 247: gridPhaseSequence [0-1]
if (params.gridPhaseSequence !== undefined) {
    let numVal = params.gridPhaseSequence;
    if (typeof numVal === 'string') {
        const map = { 'ABC_0_120_240': 0, 'ACB_0_240_120': 1 };
        numVal = map[numVal];
    }
    if (numVal === 0 || numVal === 1) {
        writes.push({ register: 247, value: numVal, name: 'Phase Sequence' });
    }
}

// ═══════════════════════════════════════════════════════════
// BATTERY SETTINGS
// ═══════════════════════════════════════════════════════════

// Register 211: batteryControlMode [0-2]
if (params.batteryControlMode !== undefined) {
    let numVal = params.batteryControlMode;
    if (typeof numVal === 'string') {
        const map = { 'voltage': 0, 'capacity': 1, 'no_battery': 2 };
        numVal = map[numVal];
    }
    if (numVal >= 0 && numVal <= 2) {
        writes.push({ register: 211, value: numVal, name: 'Battery Control Mode' });
    }
}

// ═══════════════════════════════════════════════════════════
// GENERATOR SETTINGS
// ═══════════════════════════════════════════════════════════

// Register 233: generator.inputMode [0-2]
const gen = params.generator || {};
if (gen.inputMode !== undefined) {
    let numVal = gen.inputMode;
    if (typeof numVal === 'string') {
        const map = { 'generator_input': 0, 'smart_load': 1, 'micro_inverter_input': 2 };
        numVal = map[numVal];
    }
    if (numVal >= 0 && numVal <= 2) {
        writes.push({ register: 233, value: numVal, name: 'Generator Input Mode' });
    }
}

// Register 289: generator.connectedToGridInput [0-1]
if (gen.connectedToGridInput !== undefined) {
    const val = gen.connectedToGridInput ? 1 : 0;
    writes.push({ register: 289, value: val, name: 'Gen Connected to Grid' });
}

// ═══════════════════════════════════════════════════════════
// LOAD & GRID SETTINGS
// ═══════════════════════════════════════════════════════════

// Register 242: exportLimitMode [0-2]
if (params.exportLimitMode !== undefined) {
    let numVal = params.exportLimitMode;
    if (typeof numVal === 'string') {
        const map = { 'sell_enabled': 0, 'internal_meter': 1, 'external_ct': 2 };
        numVal = map[numVal];
    }
    if (numVal >= 0 && numVal <= 2) {
        writes.push({ register: 242, value: numVal, name: 'Export Limit Mode' });
    }
}

// ═══════════════════════════════════════════════════════════
// EXECUTE
// ═══════════════════════════════════════════════════════════

if (writes.length === 0) {
    msg.operationType = 'read';
    return [null, msg];
}

global.set('scs_write_queue', writes);
global.set('scs_write_index', 0);
global.set('scs_write_results', []);
global.set('scs_write_rpc_topic', msg.rpcResponseTopic);

node.status({ fill: 'blue', shape: 'dot', text: `${writes.length} writes queued` });

return [msg, null];

const writes = global.get("scs_write_queue") || [];
const index = global.get("scs_write_index") || 0;

if (index >= writes.length) {
    return null;
}

const current = writes[index];

const newMsg = {
    payload: {
        fc: 16,
        unitid: 1,
        address: current.register,
        quantity: 1,
        value: [current.value]
    },
    currentWrite: current,
    writeIndex: index
};

node.status({ fill: "blue", shape: "dot", text: `[${index+1}/${writes.length}] ${current.name}` });

return newMsg;

const writes = global.get("scs_write_queue") || [];
let index = global.get("scs_write_index") || 0;
const results = global.get("scs_write_results") || [];

// Record success
const current = writes[index];
if (current) {
    results.push({ 
        register: current.register, 
        name: current.name, 
        value: current.value, 
        success: true 
    });
    global.set("scs_write_results", results);
}

// Move to next
index++;
global.set("scs_write_index", index);

node.status({ fill: "green", shape: "dot", text: `${current.name} OK` });

// More writes?
if (index < writes.length) {
    return [{ doNext: true }, null];
}

// All done - go to read
const rpcTopic = global.get("scs_write_rpc_topic");

global.set("scs_write_queue", null);
global.set("scs_write_index", null);
global.set("scs_write_rpc_topic", null);

const finalMsg = {
    writeResult: {
        success: true,
        message: `Successfully wrote ${results.length} register(s)`,
        writes: results
    },
    rpcResponseTopic: rpcTopic
};

global.set("scs_write_results", null);

node.status({ fill: "green", shape: "dot", text: `All ${results.length} writes OK!` });

return [null, finalMsg];
